import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../AuthContext";
import { Link } from "react-router-dom";
import '../styles/AuthStyles.css';
import '../styles/global.css';
import logo from '../images/logo.png'; // Add your logo image
import { FaEye, FaEyeSlash } from "react-icons/fa"; // Import eye icons

const Login = () => {
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });

  const [showPassword, setShowPassword] = useState(false); // State for showing/hiding password
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

 // In your Login component
 const handleSubmit = async (e) => {
  e.preventDefault();
  try {
    // Basic validation
    if (!formData.email || !formData.password) {
      throw new Error("Please fill in all fields");
    }

    const { success } = await login(formData.email, formData.password);
    
    if (success) {
      // Check if user needs to complete profile or can go to dashboard
      navigate("/profile"); // Or "/dashboard" based on your app flow
    }
  } catch (error) {
    // Show more detailed error message
    alert(error.message || "Login failed. Please try again.");
    console.error("Login error:", error);
  }
};

  return (
    <div className="auth-container">
      <div className="background-slideshow">
        <div className="slide slide1"></div>
        <div className="slide slide2"></div>
        <div className="slide slide3"></div>
      </div>
      
      <div className="auth-content">
        <img src={logo} alt="Folo Logo" className="auth-logo" />
        <div className="auth-form">
          <h1>Login</h1>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Email:</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Password:</label>
              <div className="password-input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  required
                />
                <button
                  type="button"
                  className="show-password-button"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </button>
              </div>
            </div>
            <button type="submit" className="auth-button">
              Login
            </button>
          </form>
          <p className="auth-link">
            Don&apos;t have an account? <Link to="/signup">Sign up here</Link>.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;