import React, { createContext, useState, useEffect, useCallback } from "react";
import axios from "axios";
import PropTypes from "prop-types";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isAuthenticating, setIsAuthenticating] = useState(true);

  // Check authentication status on initial load
  useEffect(() => {
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem("token");
        const refreshToken = localStorage.getItem("refreshToken");
        const userData = JSON.parse(localStorage.getItem("userData"));

        if (token && userData) {
          // Verify token is still valid
          setUser({
            token,
            refreshToken,
            ...userData,
          });
        } else if (refreshToken) {
          // Try to refresh token if access token is missing but refresh token exists
          await refreshAuth();
        }
      } catch (error) {
        console.error("Auth check error:", error);
        logout();
      } finally {
        setIsAuthenticating(false);
      }
    };

    checkAuth();
  }, []);

  const refreshAuth = useCallback(async () => {
    try {
      const refreshToken = localStorage.getItem("refreshToken");
      if (!refreshToken) throw new Error("No refresh token available");

      const response = await axios.post(
        `${process.env.REACT_APP_BACKEND_URL}/api/refresh-token`,
        { refreshToken }
      );

      const { token, refreshToken: newRefreshToken, user: userData } = response.data;

      // Store new tokens and user data
      localStorage.setItem("token", token);
      localStorage.setItem("refreshToken", newRefreshToken);
      localStorage.setItem("userData", JSON.stringify(userData));

      setUser({
        token,
        refreshToken: newRefreshToken,
        ...userData,
      });

      return token;
    } catch (error) {
      console.error("Token refresh failed:", error);
      logout();
      throw error;
    }
  }, []);

  const login = async (email, password) => {
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_BACKEND_URL}/api/login`,
        { email, password }
      );
  
      const { token, refreshToken, user: userData } = response.data;
  
      // Store auth data
      localStorage.setItem("token", token);
      localStorage.setItem("refreshToken", refreshToken);
      localStorage.setItem("userData", JSON.stringify(userData));
  
      // Update state
      setUser({
        token,
        refreshToken,
        ...userData,
      });
  
      return { success: true, user: userData }; // Return success status and user data
    } catch (error) {
      console.error("Login error:", error.response?.data || error.message);
      throw new Error(error.response?.data?.message || "Login failed. Please check your credentials.");
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem("token");
    localStorage.removeItem("refreshToken");
    localStorage.removeItem("userData");
  };

  const deleteAccount = async () => {
    try {
      await axios.post(
        `${process.env.REACT_APP_BACKEND_URL}/api/account/delete`,
        {
          userId: user?.id,
          deletionDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000),
        },
        {
          headers: {
            Authorization: `Bearer ${user?.token}`,
          },
        }
      );
      logout();
    } catch (error) {
      console.error("Account deletion failed:", error);
      throw error;
    }
  };

  const updateRole = (newRole) => {
    if (!newRole) {
      console.error("Invalid role provided to updateRole");
      return;
    }

    setUser((prev) => {
      if (!prev) {
        console.error("Cannot update role: No user logged in");
        return prev;
      }

      const updatedUser = {
        ...prev,
        role: newRole,
      };

      localStorage.setItem(
        "userData",
        JSON.stringify({
          id: updatedUser.id,
          email: updatedUser.email,
          role: newRole,
        })
      );

      return updatedUser;
    });
  };

  // Create axios instance with interceptors
  const authAxios = axios.create({
    baseURL: process.env.REACT_APP_BACKEND_URL || "http://localhost:5000",
  });

  // Add request interceptor to include token
  authAxios.interceptors.request.use(
    (config) => {
      if (user?.token) {
        config.headers.Authorization = `Bearer ${user.token}`;
      }
      return config;
    },
    (error) => Promise.reject(error)
  );

  // Add response interceptor to handle token refresh
  authAxios.interceptors.response.use(
    (response) => response,
    async (error) => {
      const originalRequest = error.config;
      
      // If error is 401 and we haven't already retried
      if (error.response?.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;
        
        try {
          const newToken = await refreshAuth();
          originalRequest.headers.Authorization = `Bearer ${newToken}`;
          return authAxios(originalRequest);
        } catch (refreshError) {
          logout();
          return Promise.reject(refreshError);
        }
      }
      
      return Promise.reject(error);
    }
  );

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticating,
        login,
        logout,
        updateRole,
        deleteAccount,
        authAxios,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

AuthProvider.propTypes = {
  children: PropTypes.node.isRequired,
};