import React, { useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";
import '../styles/AuthStyles.css';
import logo from '../images/logo.png';
import { FaEye, FaEyeSlash } from "react-icons/fa";

const SignUp = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
    role: "buyer",
    dateOfBirth: "",
    agreeToTerms: false,
  });

  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  const calculateAge = (dateOfBirth) => {
    if (!dateOfBirth) return 0;
    const today = new Date();
    const birthDate = new Date(dateOfBirth);
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  const validatePassword = (password) => {
    return {
      hasUppercase: /[A-Z]/.test(password),
      hasLowercase: /[a-z]/.test(password),
      hasNumber: /\d/.test(password),
      hasSymbol: /[!@#$%^&*(),.?":{}|<>]/.test(password),
      isLongEnough: password.length >= 8,
    };
  };

  const passwordChecks = validatePassword(formData.password);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    // Validate form
    if (!formData.name || formData.name.length < 2) {
      setError("Name must be at least 2 characters");
      return;
    }

    if (!formData.agreeToTerms) {
      setError("You must agree to the terms to sign up.");
      return;
    }

    const age = calculateAge(formData.dateOfBirth);
    if (age < 18) {
      setError("You must be at least 18 years old.");
      return;
    }

    if (!passwordChecks.isLongEnough) {
      setError("Password must be at least 8 characters.");
      return;
    }

    setIsLoading(true);

    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/auth/signup`,
        {
          name: formData.name,
          email: formData.email,
          password: formData.password,
          role: formData.role,
          dateOfBirth: formData.dateOfBirth
        },
        {
          headers: {
            'Content-Type': 'application/json'
          }
        }
      );

      if (response.data.success) {
        navigate("/login", { 
          state: { 
            successMessage: "Signup successful! Please check your email to verify your account." 
          } 
        });
      } else {
        setError(response.data.message || "Signup failed");
      }
    } catch (error) {
      if (error.response) {
        // Handle validation errors from backend
        if (error.response.data.errors) {
          setError(error.response.data.errors.map(err => err.msg).join(', '));
        } else {
          setError(error.response.data.message || "Signup failed");
        }
      } else {
        setError(error.message || "Signup failed. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="background-slideshow">
        <div className="slide slide1"></div>
        <div className="slide slide2"></div>
        <div className="slide slide3"></div>
      </div>
      
      <div className="auth-content">
        <img src={logo} alt="Folo Logo" className="auth-logo" />
        <div className="auth-form">
          <h1>Sign Up</h1>
          {error && <p className="error-message">{error}</p>}
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Name:</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
                minLength={2}
                maxLength={50}
              />
            </div>
            <div className="form-group">
              <label>Email:</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Password:</label>
              <div className="password-input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  required
                  minLength={8}
                />
                <button
                  type="button"
                  className="show-password-button"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </button>
              </div>
              {formData.password && (
                <div className="password-validation">
                  <p className={passwordChecks.hasUppercase ? "valid" : "invalid"}>
                    {passwordChecks.hasUppercase ? "✓" : "✗"} At least one uppercase letter
                  </p>
                  <p className={passwordChecks.hasLowercase ? "valid" : "invalid"}>
                    {passwordChecks.hasLowercase ? "✓" : "✗"} At least one lowercase letter
                  </p>
                  <p className={passwordChecks.hasNumber ? "valid" : "invalid"}>
                    {passwordChecks.hasNumber ? "✓" : "✗"} At least one number
                  </p>
                  <p className={passwordChecks.hasSymbol ? "valid" : "invalid"}>
                    {passwordChecks.hasSymbol ? "✓" : "✗"} At least one symbol
                  </p>
                  <p className={passwordChecks.isLongEnough ? "valid" : "invalid"}>
                    {passwordChecks.isLongEnough ? "✓" : "✗"} At least 8 characters long
                  </p>
                </div>
              )}
            </div>
            <div className="form-group">
              <label>Date of Birth:</label>
              <input
                type="date"
                name="dateOfBirth"
                value={formData.dateOfBirth}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Role:</label>
              <select 
                name="role" 
                value={formData.role} 
                onChange={handleChange}
                className="role-select"
              >
                <option value="buyer">Buyer</option>
                <option value="seller">Seller</option>
              </select>
            </div>
            <div className="form-group">
              <label>
                <input
                  type="checkbox"
                  name="agreeToTerms"
                  checked={formData.agreeToTerms}
                  onChange={handleChange}
                  required
                />
                By signing up, you agree to our{" "}
                <Link to="/terms-of-service" target="_blank" rel="noopener noreferrer">
                  Terms of Service
                </Link>
                ,{" "}
                <Link to="/privacy-policy" target="_blank" rel="noopener noreferrer">
                  Privacy Policy
                </Link>
                , and{" "}
                <Link to="/cookie-policy" target="_blank" rel="noopener noreferrer">
                  Cookie Policy
                </Link>
                .
              </label>
            </div>
            <button 
              type="submit" 
              className="auth-button"
              disabled={isLoading}
            >
              {isLoading ? "Signing Up..." : "Sign Up"}
            </button>
          </form>
          <p className="auth-link">
            Already have an account? <Link to="/login">Log in here</Link>.
          </p>
        </div>
      </div>
    </div>
  );
};

export default SignUp;